import XCTest

class SettingsTest: XCTestCase {
    func testOpenNotifications() {
        let app = XCUIApplication(bundleIdentifier: "com.apple.Preferences")
        app.activate()

        // Wait for app to load
        sleep(1)

        // Try to find and tap on Notifications
        let notificationsElement = app.tables.staticTexts["Notifications"]
        if notificationsElement.exists {
            notificationsElement.tap()
            sleep(1)
        }
    }
}
