import Foundation

// Get the device ID from environment or use the default
let deviceId = "5A7EF26A-FE07-4CF1-8C56-E2FDE03EEE5A"

// Try multiple ways to open Notifications
let commands = [
    ["xcrun", "simctl", "spawn", deviceId, "open", "-a", "Settings", "App-Prefs:root=Notifications"],
    ["xcrun", "simctl", "spawn", deviceId, "open", "App-Prefs:root=Notifications"],
]

for cmd in commands {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
    process.arguments = cmd.dropFirst()

    do {
        try process.run()
        process.waitUntilExit()
    } catch {
        print("Error running command: \(error)")
    }
}
EOF

